using System.Text.Json;using EduForge.Domain;using EduForge.Infrastructure;using Microsoft.EntityFrameworkCore;
namespace EduForge.Api;
public static class AssignmentFileEndpoints {
 public static void MapAssignmentFiles(this WebApplication app){var routes=app.MapGroup("/api/tasks/{token}/files").RequireRateLimiting("join");routes.MapPost("/",async(string token,HttpRequest request,MaterialDbContext db,CancellationToken ct)=>{var assignment=await db.Assignments.SingleOrDefaultAsync(x=>x.Token==token,ct);if(assignment is null)return Results.NotFound();if(!request.HasFormContentType)return Results.BadRequest();var form=await request.ReadFormAsync(ct);var file=form.Files.GetFile("file");if(file is null||file.Length==0||file.Length>10*1024*1024)return Results.BadRequest(new{message="Загрузите изображение или GLB до 10 МБ."});using var stream=new MemoryStream();await file.CopyToAsync(stream,ct);var data=stream.ToArray();string? type=data.Length>=8&&data.AsSpan(0,8).SequenceEqual(new byte[]{137,80,78,71,13,10,26,10})?"image/png":data.Length>=3&&data[0]==255&&data[1]==216&&data[2]==255?"image/jpeg":null;if(data.Length>=20&&System.Text.Encoding.ASCII.GetString(data,0,4)=="glTF"){try{var length=BitConverter.ToInt32(data,12);if(BitConverter.ToInt32(data,4)!=2||BitConverter.ToInt32(data,8)!=data.Length||BitConverter.ToInt32(data,16)!=0x4E4F534A||length<=0||length>data.Length-20)return Results.BadRequest();using var json=JsonDocument.Parse(data.AsMemory(20,length));foreach(var key in new[]{"buffers","images"})if(json.RootElement.TryGetProperty(key,out var entries))foreach(var entry in entries.EnumerateArray())if(entry.TryGetProperty("uri",out var uri)&&!(uri.GetString()??"").StartsWith("data:"))return Results.BadRequest(new{message="GLB должен содержать встроенные ресурсы без внешних ссылок."});type="model/gltf-binary";}catch{return Results.BadRequest(new{message="Некорректная модель GLB."});}}if(type is null)return Results.BadRequest(new{message="Поддерживаются PNG, JPEG и GLB."});var asset=new MediaAsset{TeacherId=assignment.TeacherId,ContentType=type,Data=data};db.MediaAssets.Add(asset);db.AssignmentAssets.Add(new AssignmentAsset{Id=asset.Id,AssignmentId=assignment.Id,Name=Path.GetFileName(file.FileName)[..Math.Min(Path.GetFileName(file.FileName).Length,200)]});await db.SaveChangesAsync(ct);return Results.Ok(new{url=$"/api/tasks/{token}/files/{asset.Id}",type});});
 routes.MapGet("/{id:guid}",async(string token,Guid id,MaterialDbContext db,HttpResponse response,CancellationToken ct)=>{var assignmentId=await db.Assignments.Where(x=>x.Token==token).Select(x=>(Guid?)x.Id).SingleOrDefaultAsync(ct);if(assignmentId is null||!await db.AssignmentAssets.AnyAsync(x=>x.Id==id&&x.AssignmentId==assignmentId,ct))return Results.NotFound();var asset=await db.MediaAssets.SingleAsync(x=>x.Id==id,ct);response.Headers["X-Content-Type-Options"]="nosniff";return Results.File(asset.Data,asset.ContentType);});
 }
}
